import{c as r,Q as t,j as a,m as s}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse('{"title":"Engineering Robustness into Personal Agents with the AI Workflow Store","description":"","frontmatter":{"url":"https://arxiv.org/abs/2605.10907","title":"Engineering Robustness into Personal Agents with the AI Workflow Store","archived_date":"2026-07-18T00:00:00.000Z","arxiv_id":2605.10907,"authors":["Roxana Geambasu","Mariana Raykova","Pierre Tholoniat","Trishita Tiwari","Lillian Tsai","Wen Zhang"],"pdf_path":"pdfs/2605.10907.pdf","published_date":"2026-05-11T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-05-11-engineering-robustness-personal-agents-ai-workflow-store-2605-10907.md","filePath":"research/papers/2026-05-11-engineering-robustness-personal-agents-ai-workflow-store-2605-10907.md","lastUpdated":1785909234000}'),o={name:"research/papers/2026-05-11-engineering-robustness-personal-agents-ai-workflow-store-2605-10907.md"};function n(i,e,l,h,g,d){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="engineering-robustness-into-personal-agents-with-the-ai-workflow-store" tabindex="-1">Engineering Robustness into Personal Agents with the AI Workflow Store <a class="header-anchor" href="#engineering-robustness-into-personal-agents-with-the-ai-workflow-store" aria-label="Permalink to &quot;Engineering Robustness into Personal Agents with the AI Workflow Store&quot;">​</a></h1><p><strong>Authors</strong>: Roxana Geambasu, Mariana Raykova, Pierre Tholoniat, Trishita Tiwari, Lillian Tsai, Wen Zhang <strong>Published</strong>: May 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2605.10907" target="_blank" rel="noreferrer">https://arxiv.org/abs/2605.10907</a><strong>arXiv ID</strong>: 2605.10907 <strong>Categories</strong>: Cryptography and Security (cs.CR); Artificial Intelligence (cs.AI) <strong>PDF</strong>: <a href="https://arxiv.org/abs/2605.10907" target="_blank" rel="noreferrer">research/papers/pdfs/2605.10907.pdf</a></p><hr><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>The paper critiques the prevailing &quot;on-the-fly&quot; agent paradigm, arguing it short-circuits disciplined software engineering processes. The authors contend that rapid real-time synthesis may deliver improvised prototypes rather than systems fit for high-stakes scenarios where reliability matters. They propose integrating rigorous engineering practices to create production-grade, hardened, and deterministically-constrained agent workflows that exceed the robustness of improvised approaches. To manage the computational overhead, they suggest amortizing costs through community reuse. The core vision centers on an &quot;AI Workflow Store&quot; comprising pre-hardened, reusable workflows offering substantially greater reliability and security than improvised tool chains. The research addresses fundamental tensions between flexibility and robustness that necessitate moving beyond on-the-fly methodologies.</p><hr><h2 id="core-thesis" tabindex="-1">Core Thesis <a class="header-anchor" href="#core-thesis" aria-label="Permalink to &quot;Core Thesis&quot;">​</a></h2><ul><li>批評主流「on-the-fly」agent 範式（每次即時合成執行計畫）繞過紮實的軟體工程流程，高風險場景下產出的常是「臨場拼裝原型」而非可靠系統。</li><li>主張導入嚴謹工程實踐，把 workflow 打造成「production-grade、hardened、確定性約束」而非即興生成，並透過社群重用（reusable workflow）分攤工程成本。</li><li>提出 &quot;AI Workflow Store&quot; 願景：預先硬化過、可重用的 workflow 集合，比臨場拼裝的工具鏈更可靠、更安全。</li><li><strong>Workspace 關聯</strong>：與 core.md「規範優先」及 APPLY 章「既有慣例 &gt; 個人偏好」精神一致——本文主張「可重用、預先硬化的 workflow」而非每次臨場決策，呼應本 workspace 用 skills/agents/hooks 固化重複性任務流程（而非每次讓 LLM 即興規劃）的設計取向。</li></ul>',8)])])}const u=r(o,[["render",n]]);export{c as __pageData,u as default};
